//! Token accounting — budget enforcement and usage ledger.
//!
//! After each [`Provider::complete`](super::Provider::complete) call the
//! caller forwards the [`TokenUsage`](super::TokenUsage) to a
//! [`TokenAccounting`] hook.  The hook can enforce budgets, log usage, or
//! feed metrics to the telemetry plugin — without coupling the provider
//! itself to any particular accounting policy.
//!
//! [`TokenLedger`] is the default concrete implementation: it tracks
//! cumulative usage per model, enforces an optional per-run budget, and
//! produces a serializable summary suitable for appending to council
//! trace records.

use std::collections::HashMap;

use serde::{Deserialize, Serialize};

use super::TokenUsage;

// ---------------------------------------------------------------------------
// UsageEvent — the unit of accounting
// ---------------------------------------------------------------------------

/// A single token-usage observation forwarded from a provider completion.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UsageEvent {
    /// Model that produced the completion.
    pub model: String,
    /// Council stage that requested the completion (e.g. `"gemini"`, `"claude"`).
    pub stage: String,
    /// Token counts.
    pub usage: TokenUsage,
    /// ISO-8601 timestamp of the completion.
    pub timestamp: String,
}

// ---------------------------------------------------------------------------
// TokenBudget
// ---------------------------------------------------------------------------

/// An optional ceiling on total token consumption for a run.
#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
pub struct TokenBudget {
    /// Maximum total (input + output) tokens allowed.
    pub max_total_tokens: u64,
}

impl TokenBudget {
    #[must_use]
    pub fn new(max_total_tokens: u64) -> Self {
        Self { max_total_tokens }
    }

    /// How many tokens remain given `consumed` so far.
    #[must_use]
    pub fn remaining(&self, consumed: u64) -> u64 {
        self.max_total_tokens.saturating_sub(consumed)
    }

    /// Whether the budget would be exceeded by an additional `requested`.
    #[must_use]
    pub fn would_exceed(&self, consumed: u64, requested: u64) -> bool {
        consumed.saturating_add(requested) > self.max_total_tokens
    }
}

// ---------------------------------------------------------------------------
// TokenAccounting trait
// ---------------------------------------------------------------------------

/// Hook invoked after every provider completion.
///
/// Implementations decide what to *do* with the usage data: enforce budgets,
/// write to a ledger file, send to telemetry, etc.
pub trait TokenAccounting: Send + Sync {
    /// Record a completed usage event.
    ///
    /// Returns `Err` if the budget is exhausted and the caller should stop
    /// issuing further completions.
    fn record(&mut self, event: &UsageEvent) -> Result<(), BudgetExceeded>;

//! Tokenizer trait and built-in estimators.
//!
//! Provider implementations expose a [`Tokenizer`] so callers can estimate
//! token counts *before* submitting a request.  This enables:
//!
//! - **Pre-flight budget checks**: reject prompts that would exceed the
//!   remaining budget before consuming any API quota.
//! - **Context-window fitting**: truncate or summarise context to stay
//!   within the model's window.
//! - **Cost forecasting**: display estimated cost before expensive runs.
//!
//! When a provider-specific tokenizer (e.g. tiktoken for `OpenAI`, or the
//! Claude tokenizer) is not available, [`CharEstimateTokenizer`] provides a
//! reasonable heuristic (≈ 4 characters per token for English text).

use super::{InputMessage, Request};

// ---------------------------------------------------------------------------
// Trait
// ---------------------------------------------------------------------------

/// Estimate token counts for text or structured requests.
///
/// Implementations may be exact (using the model's actual tokenizer) or
/// heuristic (character-ratio estimation).  The [`is_exact`](Tokenizer::is_exact)
/// method lets callers decide how much margin to add.
pub trait Tokenizer: Send + Sync {
    /// Whether this tokenizer produces exact counts for the target model.
    fn is_exact(&self) -> bool;

    /// Estimate the number of tokens in a raw text string.
    fn count_text(&self, text: &str) -> u64;

    /// Estimate the total input tokens for a full [`Request`].
    ///
    /// The default implementation sums per-message estimates plus a small
    /// overhead for message framing (role tags, separators).  Provider-
    /// specific implementations can override this for higher accuracy.
    fn count_request(&self, request: &Request) -> u64 {
        let mut total: u64 = 0;
        for msg in &request.input {
            // ~4 tokens for message framing (role, separators).
            total = total.saturating_add(4);
            total = total.saturating_add(self.count_text(&msg.content));
        }
        // +2 for the reply priming tokens.
        total.saturating_add(2)
    }

    /// Estimate tokens for a single [`InputMessage`].
    fn count_message(&self, message: &InputMessage) -> u64 {
        self.count_text(&message.content).saturating_add(4)
    }
}

// ---------------------------------------------------------------------------
// CharEstimateTokenizer
// ---------------------------------------------------------------------------

/// Character-ratio tokenizer — ≈ `chars_per_token` characters map to one token.
///
/// This is intentionally conservative (defaults to 4.0 for English) so that
/// budget pre-flight checks over-estimate rather than under-estimate.
///
/// Use this as the fallback when a model-specific tokenizer is unavailable.
#[derive(Debug, Clone)]
pub struct CharEstimateTokenizer {
    chars_per_token: f64,
}

impl CharEstimateTokenizer {
    /// Default ratio suitable for English text with the major LLM tokenizers.
    const DEFAULT_CHARS_PER_TOKEN: f64 = 4.0;

    /// Create a tokenizer with the default 4-chars-per-token ratio.
    #[must_use]
    pub fn new() -> Self {
        Self {
            chars_per_token: Self::DEFAULT_CHARS_PER_TOKEN,
        }

//! Token accounting and budget enforcement.
//!
//! Provides a [`TokenAccountant`] that tracks cumulative token usage per session
//! and enforces budgets before provider calls. This is the internal "hooks" layer
//! that sits between the runtime and the provider — every request passes through
//! budget validation, and every response records usage.

use std::collections::HashMap;
use std::sync::Arc;

use parking_lot::RwLock;
use tracing::{debug, warn};

use layers_core::error::{LayersError, Result};
use layers_core::traits::{ModelProvider, Tokenizer};
use layers_core::types::*;

// ---------------------------------------------------------------------------
// Usage snapshot
// ---------------------------------------------------------------------------

/// Cumulative token usage for a single session.
#[derive(Debug, Clone, Default)]
pub struct UsageSnapshot {
    /// Total prompt tokens consumed across all requests.
    pub prompt_tokens: usize,
    /// Total completion tokens consumed across all requests.
    pub completion_tokens: usize,
    /// Total reasoning tokens (extended thinking) consumed.
    pub reasoning_tokens: usize,
    /// Total cache-read tokens (prompt caching savings).
    pub cache_read_tokens: usize,
    /// Number of provider calls recorded.
    pub request_count: usize,
}

impl UsageSnapshot {
    /// Merge a single-request `Usage` into this snapshot.
    pub fn record(&mut self, usage: &Usage) {
        self.prompt_tokens += usage.prompt_tokens;
        self.completion_tokens += usage.completion_tokens;
        self.reasoning_tokens += usage.reasoning_tokens.unwrap_or(0);
        self.cache_read_tokens += usage.cache_read_tokens.unwrap_or(0);
        self.request_count += 1;
    }

    /// Total tokens (prompt + completion + reasoning).
    pub fn total(&self) -> usize {
        self.prompt_tokens + self.completion_tokens + self.reasoning_tokens
    }
}

// ---------------------------------------------------------------------------
// Accounting key
// ---------------------------------------------------------------------------

/// Key for looking up usage by session and agent.
#[derive(Debug, Clone, Hash, Eq, PartialEq)]
pub struct AccountingKey {
    pub session_id: String,
    pub agent_id: String,
}

impl AccountingKey {
    pub fn new(session_id: impl Into<String>, agent_id: impl Into<String>) -> Self {
        Self {
            session_id: session_id.into(),
            agent_id: agent_id.into(),
        }
    }
}

// ---------------------------------------------------------------------------
// Budget check result
// ---------------------------------------------------------------------------

/// Result of a pre-flight budget check.
#[derive(Debug, Clone)]
pub struct BudgetCheck {
    /// Estimated input tokens for the pending request.

